            ix = [(i,j) for i in range(length) for j in range(i+1,length)]
            distance = float(np.sqrt(np.mean([(past[j]-past[i]-(q[j]-q[i]))**2 for i,j in ix])))
            interval = following-past[-1]
        if distance <= config.get(name+'_cutoff', .3):
